mapper.insert:


        SELECT SBA131_SQ01.NEXTVAL AS UNITY_CMNT_SN
          FROM DUAL



/* 공통팀 유민상 sry.itgcms.itgBrd.mapper.ItgBrdCmnCmntMapper.insertItgBrdCmntList 공통팀 유민상 */
INSERT INTO SBA131(
      UNITY_BBSCTT_ESNTAL_NO
    , UNITY_CMNT_SN
    , OGDP_INST_NO
    , OGDP_DEPT_CD
    , UNITY_CMNT_CN

        , ATFINO

    , CNTN_IP_ADDR
    , DEL_YN

        , TASKWK_PRCS_SE_CD


        , TASKWK_TASKFO_SE_CD

    , FRST_RGTR_ID
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
)VALUES(
      #{UNITY_BBSCTT_ESNTAL_NO}
    , #{UNITY_CMNT_SN}
    , #{OGDP_INST_NO}
    , #{OGDP_DEPT_CD}
    , #{UNITY_CMNT_CN}

        , #{ATFINO}

    , #{CNTN_IP_ADDR}
    , 'N'

        , #{TASKWK_PRCS_SE_CD}


        , #{TASKWK_TASKFO_SE_CD}

    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE
)

mapper.update:
/* 공통팀 유민상 sry.itgcms.itgBrd.mapper.ItgBrdCmnCmntMapper.updateItgBrdCmntList 공통팀 유민상 */
UPDATE SBA131 SET
    UNITY_CMNT_CN = #{UNITY_CMNT_CN}

        , ATFINO = #{ATFINO}

    , LAST_MDFCN_DT = SYSDATE
    , LAST_MDFR_ID = #{LAST_MDFR_ID}

WHERE 1=1
AND UNITY_BBSCTT_ESNTAL_NO = #{UNITY_BBSCTT_ESNTAL_NO__origin}
AND UNITY_CMNT_SN = #{UNITY_CMNT_SN__origin}

/* 공통팀 유민상 sry.itgcms.itgBrd.mapper.ItgBrdCmnCmntMapper.deleteItgBrdCmntList 공통팀 유민상 */
UPDATE SBA131 SET
      DEL_YN = 'Y'
    , LAST_MDFCN_DT = SYSDATE
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND UNITY_BBSCTT_ESNTAL_NO = #{UNITY_BBSCTT_ESNTAL_NO__origin}
AND UNITY_CMNT_SN = #{UNITY_CMNT_SN__origin}
